insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 24, 'E o povo respondeu a Josué: Ao SENHOR nosso Deus serviremos, e à sua voz obedeceremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 25, 'Então Josué fez aliança com o povo o mesmo dia, e pôs-lhe ordenanças e leis em Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 26, 'E escreveu Josué estas palavras no livro da lei de Deus; e tomando uma grande pedra, levantou-a ali debaixo de um carvalho que estava junto ao santuário do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 27, 'E disse Josué a todo o povo: Eis que esta pedra será entre nós por testemunha, a qual ouviu todas as palavras do SENHOR que ele falou conosco: será, pois, testemunha contra vós, para que não mintais contra vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 28, 'E enviou Josué ao povo, cada um à sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 29, 'E depois destas coisas morreu Josué, filho de Num, servo do SENHOR sendo de cento e dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 30, 'E enterraram-no no termo de sua possessão em Timnate-Sera, que está no monte de Efraim, ao norte do monte de Gaás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 31, 'E serviu Israel ao SENHOR todo o tempo de Josué, e todo o tempo dos anciãos que viveram depois de Josué, e que sabiam todas as obras do SENHOR, que havia feito por Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 32, 'E enterraram em Siquém os ossos de José que os filhos de Israel haviam trazido do Egito, na parte do campo que Jacó comprou dos filhos de Hamor, pai de Siquém, por cem peças de prata; e foi em possessão aos filhos de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 33, 'Também morreu Eleazar, filho de Arão; ao qual enterraram no morro de Fineias seu filho, que lhe foi dado no monte de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 1, 'E aconteceu depois da morte de Josué, que os filhos de Israel consultaram ao SENHOR, dizendo: Quem subirá por nós primeiro para lutar contra os cananeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 2, 'E o SENHOR respondeu: Judá subirá; eis que eu entreguei a terra em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 3, 'E Judá disse a Simeão seu irmão: Sobe comigo à minha porção, e lutemos contra os cananeus, e eu também irei contigo à tua porção. E Simeão foi com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 4, 'E subiu Judá, e o SENHOR entregou em suas mãos aos cananeus e aos perizeus; e deles feriram em Bezeque dez mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 5, 'E acharam a Adoni-Bezeque em Bezeque, e lutaram contra ele: e feriram aos cananeus e aos perizeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 6, 'Mas Adoni-Bezeque fugiu; e seguiram-no, e prenderam-no, e cortaram-lhe os polegares das mãos e dos pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 7, 'Então disse Adoni-Bezeque: Setenta reis, cortados os polegares de suas mãos e de seus pés, colhiam as migalhas debaixo de minha mesa: como eu fiz, assim Deus me pagou. E meteram-no em Jerusalém, de onde morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 8, 'E combateram os filhos de Judá a Jerusalém, e a tomaram, e puseram à espada, e puseram a fogo a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 9, 'Depois os filhos de Judá desceram para lutar contra os cananeus que habitavam nas montanhas, e ao sul, e nas planícies.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 10, 'E partiu Judá contra os cananeus que habitavam em Hebrom, a qual se chamava antes Quiriate-Arba; e feriram a Sesai, e a Aimã, e a Talmai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 11, 'E dali foi aos que habitavam em Debir, que antes se chamava Quiriate-Sefer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 12, 'E disse Calebe: O que ferir a Quiriate-Sefer, e a tomar, eu lhe darei a Acsa minha filha por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 13, 'E tomou-a Otniel filho de Quenaz, irmão menor de Calebe: e ele lhe deu a Acsa sua filha por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 14, 'E quando a levavam, persuadiu-lhe que pedisse a seu pai um campo. E ela desceu do asno, e Calebe lhe disse: Que tens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 15, 'Ela então lhe respondeu: Dá-me uma bênção: pois me deste terra de secura, que me dês também fontes de águas. Então Calebe lhe deu as fontes de acima e as fontes de abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 16, 'E os filhos de queneu, sogro de Moisés, subiram da cidade das palmeiras com os filhos de Judá ao deserto de Judá, que está ao sul de Arade: e foram e habitaram com o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 17, 'E foi Judá ao seu irmão Simeão, e feriram aos cananeus que habitavam em Zefate, e assolaram-na: e puseram por nome à cidade, Hormá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 18, 'Tomou também Judá a Gaza com seu termo, e a Asquelom com seu termo, e a Ecrom com seu termo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 19, 'E o SENHOR foi com Judá, e expulsaram os das montanhas; mas não puderam expulsar os que habitavam nas planícies, os quais tinham carros de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 20, 'E deram Hebrom a Calebe, como Moisés havia dito: e ele expulsou dali três filhos de Anaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 21, 'Mas aos jebuseus que habitavam em Jerusalém, não expulsaram os filhos de Benjamim, e tanto os jebuseus habitaram com os filhos de Benjamim em Jerusalém até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 22, 'Também os da casa de José subiram a Betel; e o SENHOR foi com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 23, 'E os da casa de José puseram espias em Betel, a qual cidade antes se chamava Luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 24, 'E os que espiavam viram um homem que saía da cidade, e disseram-lhe: Mostra-nos agora a entrada da cidade, e faremos contigo misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 25, 'E ele lhes mostrou a entrada à cidade, e feriram-na a fio de espada; mas deixaram a aquele homem com toda sua família.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 26, 'E fosse o homem à terra dos heteus, e edificou uma cidade, à qual chamou Luz; e este é seu nome até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 27, 'Tampouco Manassés expulsou os de Bete-Seã, nem aos de suas aldeias, nem aos de Taanaque e suas aldeias, nem os de Dor e suas aldeias, nem os habitantes de Ibleão e suas aldeias, nem aos que habitavam em Megido e em suas aldeias; mas os cananeus quiseram habitar nessa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 28, 'Porém quando Israel tomou forças fez aos cananeus tributários, mas não o expulsou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 29, 'Também Efraim não expulsou os cananeus que habitavam em Gezer; antes habitaram os cananeus em meio deles em Gezer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 30, 'Também Zebulom não expulsou aos que habitavam em Quitrom e aos que habitavam em Naalol; mas os cananeus habitaram no meio dele, e lhe foram tributários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 31, 'Também Aser não expulsou aos que habitavam em Aco, e aos que habitavam em Sidom, Alabe, Aczibe, Helba, Afeque, e em Reobe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 32, 'em vez disso, Aser morou entre os cananeus que habitavam na terra; pois não os expulsou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 33, 'Também Naftali não expulsou os que habitavam em Bete-Semes e os que habitavam em Bete-Anate, mas morou entre os cananeus que habitavam na terra; todavia, os moradores de Bete-Semes e os moradores de Bete-Anate foram-lhe tributários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 34, 'Os amorreus pressionaram os filhos de Dã até as montanhas; pois não os permitiram descer ao vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 35, 'E os amorreus quiseram habitar no monte de Heres, em Aijalom e em Saalbim; mas a mão da tribo de José foi mais forte, e os fizeram tributários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 1, 36, 'E o limite dos amorreus foi desde a subida de Acrabim, desde a rocha, e daí acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 1, 'E o anjo do SENHOR subiu de Gilgal a Boquim, e disse: “Eu vos tirei do Egito, e vos introduzi na terra da qual havia jurado a vossos pais; e disse: ‘Não invalidarei jamais meu pacto convosco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 2, 'contanto que vós não façais aliança com os moradores desta terra, cujos altares deveis derrubar’; mas vós não atendestes à minha voz: por que fizestes isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 3, 'Por isso eu também disse: ‘Não os expulsarei de diante de vós, mas serão vossos inimigos, e seus deuses vos serão uma armadilha’”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 4, 'E quando o anjo do SENHOR falou estas palavras a todos os filhos de Israel, o povo chorou em alta voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 5, 'E chamaram por nome aquele lugar Boquim: e sacrificaram ali ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 6, 'Porque já Josué havia despedido ao povo, e os filhos de Israel se haviam ido cada um à sua herança para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 7, 'E o povo havia servido ao SENHOR todo aquele tempo de Josué, e todo aquele tempo dos anciãos que viveram longos dias depois de Josué, os quais viram todas as grandes obras do SENHOR, que o havia feito por Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 8, 'E morreu Josué filho de Num, servo do SENHOR, sendo de cento e dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 9, 'E enterraram-no no termo de sua herança em Timnate-Heres, no monte de Efraim, o norte do monte de Gaás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 10, 'E toda aquela geração foi também recolhida com seus pais. E levantou-se depois dela outra geração, que não conhecia o SENHOR, nem a obra que ele havia feito por Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 11, 'E os filhos de Israel fizeram o que era mal aos olhos do SENHOR, e serviram aos baalins;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 12, 'E abandonaram o SENHOR, o Deus de seus pais, que os havia tirado da terra do Egito, e seguiram outros deuses, os deuses dos povos que estavam em seus arredores, aos quais adoraram, e provocaram à ira ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 13, 'Pois abandonaram o SENHOR, e adoraram a Baal e a Astarote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 14, 'Então a fúria do SENHOR se acendeu contra Israel, e os entregou nas mãos de saqueadores que os despojaram, e os vendeu nas mãos de seus inimigos ao redor; e não puderam mais resistir diante dos seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 15, 'Por de onde quer que saíssem, a mão do SENHOR era contra eles para o mal, como o SENHOR havia dito, e como o SENHOR lhes havia jurado; assim estiveram em grande aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 16, 'Mas o SENHOR suscitou juízes que os livrassem da mão dos que os despojavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 17, 'Mas também não ouviram aos seus juízes; em vez disso, prostituíram-se seguindo outros deuses, aos quais adoraram; desviaram-se depressa do caminho em que seus pais andaram, obedecendo aos mandamentos do SENHOR; porém eles não fizeram assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 18, 'E quando o SENHOR lhes suscitava juízes, o SENHOR era com o juiz, e os livrava da mão dos inimigos todo aquele tempo daquele juiz, porque o SENHOR se arrependia pelo gemideles, por causa dos que os oprimiam e afligiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 19, 'Mas acontecia que, quando o juiz morria, eles se voltavam para trás, e se corrompiam mais que seus pais, seguindo outros deuses para os adorarem e se inclinarem diante deles; e nada cessavam de suas obras, nem de seu teimoso caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 20, 'Então a ira do SENHOR se acendeu contra Israel, e disse: “Visto que este povo transgride o meu pacto que ordenei aos seus pais, e não dá ouvidos à minha voz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 21, 'eu também não expulsarei mais de diante deles a nenhuma das nações que Josué deixou quando morreu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 22, 'para que por elas eu provasse os israelitas, se guardariam o caminho do SENHOR andando por ele, como seus pais o guardaram, ou não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 2, 23, 'Por isso o SENHOR deixou aquelas nações, e não as tirou logo, nem as entregou nas mãos de Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 1, 'Estas, pois, são as nações que o SENHOR deixou para provar com elas a Israel, a todos aqueles que não haviam conhecido todas as guerras de Canaã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 2, 'Somente para que a linhagem dos filhos de Israel conhecesse, para ensiná-los na guerra, pelo menos aos que antes não a conheciam:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 3, 'Cinco príncipes dos filisteus, e todos os cananeus, e os sidônios, e os heveus que habitavam no monte Líbano: desde o monte de Baal-Hermom até chegar a Hamate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 4, 'Estes, pois, foram para provar por eles a Israel, para saber se obedeceriam aos mandamentos do SENHOR, que ele havia prescrito a seus pais por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 5, 'Assim os filhos de Israel habitavam entre os cananeus, heteus, amorreus, perizeus, heveus, e jebuseus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 6, 'E tomaram de suas filhas por mulheres, e deram suas filhas aos filhos deles, e serviram a seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 7, 'Fizeram, pois, os filhos de Israel o mal aos olhos do SENHOR: e esquecidos do SENHOR seu Deus, serviram aos baalins, e aos ídolos dos bosques.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 8, 'E a ira do SENHOR se acendeu contra Israel, e vendeu-os em mãos de Cusã-Risataim rei da Mesopotâmia; e serviram os filhos de Israel a Cusã-Risataim oito anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 9, 'E clamaram os filhos de Israel ao SENHOR; e o SENHOR suscitou salvador aos filhos de Israel e livrou-os; é, a saber, a Otniel filho de Quenaz, irmão menor de Calebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 10, 'E o espírito do SENHOR foi sobre ele, e julgou a Israel, e saiu à batalha, e o SENHOR entregou em sua mão a Cusã-Risataim, rei da Síria, e prevaleceu sua mão contra Cusã-Risataim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 11, 'E repousou a terra quarenta anos; e morreu Otniel, filho de Quenaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 12, 'E voltaram os filhos de Israel a fazer o mal ante os olhos do SENHOR; e o SENHOR esforçou a Eglom rei de Moabe contra Israel, porquanto fizeram o mal ante os olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 13, 'E Juntou consigo aos filhos de Amom e de Amaleque, e foi, e feriu a Israel, e tomou a cidade das palmeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 14, 'E serviram os filhos de Israel a Eglom rei dos moabitas dezoito anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 15, 'E clamaram os filhos de Israel ao SENHOR; e o SENHOR lhes suscitou salvador, a Eúde, filho de Gera, benjamita, o qual era canhoto. E os filhos de Israel enviaram com ele um presente a Eglom rei de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 16, 'E Eúde se havia feito um punhal de dois fios, de um côvado de comprimento; e cingiu-se com ele debaixo de suas roupas à seu lado direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 17, 'E apresentou o presente a Eglom rei de Moabe; e era Eglom homem muito gordo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 18, 'E logo que apresentou o presente, despediu à gente que o havia trazido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 19, 'Mas ele se virou desde os ídolos que estão em Gilgal, e disse: Rei, uma palavra secreta tenho que dizer-te. Ele então disse: Cala. E sairam-se de com ele todos os que diante dele estavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 20, 'E chegou-se Eúde a ele, o qual estava sentado sozinho em uma sala de verão. E Eúde disse: Tenho palavra de Deus para ti. Ele então se levantou da cadeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 21, 'Mas Eúde meteu sua mão esquerda, e tomou o punhal de seu lado direito, e meteu-o pelo ventre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 22, 'De tal maneira que a empunhadura entrou também atrás a lâmina, e a gordura encerrou a lâmina, que ele não tirou o punhal de seu ventre: e saiu dele fezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 23, 'E saindo Eúde ao pátio, fechou atrás si as portas da sala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 24, 'E saído ele, vieram seus servos, os quais vendo as portas da sala fechadas, disseram: Sem dúvida ele está fazendo suas necessidades na sala de verão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 25, 'E havendo esperado até estar confusos, pois que ele não abria as portas da sala, tomaram a chave e abriram: e eis que seu senhor caído em terra morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 26, 'Mas enquanto que eles se demoravam, Eúde se escapou, e passando os ídolos, salvou-se em Seirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 27, 'E quando entrou, tocou a trombeta no monte de Efraim, e os filhos de Israel desceram com ele do monte, e ele ia adiante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 28, 'Então ele lhes disse: Segui-me, porque o SENHOR entregou vossos inimigos os moabitas em vossas mãos. E desceram atrás dele, e tomaram os vaus do Jordão a Moabe, e não deixaram passar a ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 29, 'E naquele tempo feriram dos moabitas como dez mil homens, todos valentes e todos homens de guerra; não escapou homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 30, 'Assim restou Moabe subjugado aquele dia sob a mão de Israel: e repousou a terra oitenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 3, 31, 'Depois deste foi Sangar filho de Anate, o qual feriu seiscentos homens dos filisteus com uma aguilhada de bois; e ele também salvou a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 1, 'Mas os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR, depois da morte de Eúde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 2, 'E o SENHOR os vendeu em mão de Jabim rei de Canaã, o qual reinou em Hazor: e o capitão de seu exército se chamava Sísera, e ele habitava em Harosete das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 3, 'E os filhos de Israel clamaram ao SENHOR, porque aquele tinha novecentos carros de ferro: e havia afligido em grande maneira aos filhos de Israel por vinte anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 4, 'E governava naquele tempo a Israel uma mulher, Débora, profetisa, mulher de Lapidote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 5, 'A qual se sentava debaixo da palmeira de Débora entre Ramá e Betel, no monte de Efraim: e os filhos de Israel subiam a ela a juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 6, 'E ela mandou chamar a Baraque filho de Abinoão, de Quedes de Naftali, e disse-lhe: Não te mandou o SENHOR Deus de Israel, dizendo: Vai, e ajunta gente no monte de Tabor, e toma contigo dez mil homens dos filhos de Naftali, e dos filhos de Zebulom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 7, 'E eu atrairei a ti ao ribeiro de Quisom a Sísera, capitão do exército de Jabim, com seus carros e seu exército, e o entregarei em tuas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 8, 'E Baraque lhe respondeu: Se tu fores comigo, eu irei: mas se não fores comigo, não irei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 9, 'E ela disse: Irei contigo; mas não será tua honra no caminho que vais; porque por mão de mulher venderá o SENHOR a Sísera. E levantando-se Débora foi com Baraque a Quedes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 10, 'E juntou Baraque a Zebulom e a Naftali em Quedes, e subiu com dez mil homens a seu mando, e Débora subiu com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 11, 'E Héber queneu, dos filhos de Hobabe sogro de Moisés, havia se afastado dos queneus, e posto sua tenda até o vale de Zaanim, que está junto a Quedes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 12, 'Vieram, pois, as notícias a Sísera como Baraque filho de Abinoão havia subido ao monte de Tabor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 13, 'E reuniu Sísera todos os seus carros, novecentos carros de ferro, com todo o povo que com ele estava, desde Harosete das Nações até o ribeiro de Quisom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 14, 'Então Débora disse a Baraque: Levanta-te; porque este é o dia em que o SENHOR entregou a Sísera em tuas mãos: Não saiu o SENHOR diante de ti? E Baraque desceu do monte de Tabor, e dez mil homens atrás dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 15, 'E o SENHOR derrotou a Sísera, e a todos os seus carros e a todo seu exército, a fio de espada diante de Baraque: e Sísera desceu do carro, e fugiu a pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 16, 'Mas Baraque seguiu os carros e o exército até Harosete das Nações, e todo aquele exército de Sísera caiu a fio de espada até não restar nenhum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 17, 'E Sísera se refugiou a pé à tenda de Jael mulher de Héber queneu; porque havia paz entre Jabim rei de Hazor e a casa de Héber queneu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 18, 'E saindo Jael a receber a Sísera, disse-lhe: Vem, senhor meu, vem a mim, não tenhas medo. E ele veio a ela à tenda, e ela lhe cobriu com uma manta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 19, 'E ele lhe disse: Rogo-te me dês a beber um pouco de água, que tenho sede. E ela abriu um odre de leite e deu-lhe de beber, e voltou-lhe a cobrir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 20, 'E ele lhe disse: Fica-te à porta da tenda, e se alguém vier, e te perguntar, dizendo: Há aqui alguém? Tu responderás que não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 21, 'E Jael, mulher de Héber, tomou uma estaca da tenda, e pondo uma marreta em sua mão, veio a ele caladamente, e meteu-lhe a estaca pela têmpora, e encravou-o na terra, pois ele estava carregado de sonho e cansado; e assim morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 22, 'E seguindo Baraque a Sísera, Jael saiu a recebê-lo, e disse-lhe: Vem, e te mostrarei ao homem que tu buscas. E ele entrou de onde ela estava, e eis que Sísera jazia morto com a estaca pela têmpora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 23, 'Assim abateu Deus aquele dia a Jabim, rei de Canaã, diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 4, 24, 'E a mão dos filhos de Israel começou a crescer e a fortificar-se contra Jabim rei de Canaã, até que o destruíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 1, 'E aquele dia cantou Débora, com Baraque, filho de Abinoão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 2, 'Porque vingou as injúrias de Israel, Porque o povo se ofereceu de sua vontade, Louvai ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 3, 'Ouvi, reis; estai atentos, ó príncipes: Eu cantarei ao SENHOR, Cantarei salmos ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 4, 'Quando saíste de Seir, ó SENHOR, Quando te apartaste do campo de Edom, A terra tremeu, e os céus destilaram, E as nuvens gotejaram águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 5, 'Os montes se derreteram diante do SENHOR, Até o Sinai, diante do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 6, 'Em os dias de Sangar filho de Anate, Em os dias de Jael, cessaram os caminhos, E os que andavam pelas sendas apartavam-se por veredas torcidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 7, 'As aldeias haviam cessado em Israel, haviam decaído; Até que eu Débora me levantei, Me levantei mãe em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 8, 'Em escolhendo novos deuses, A guerra estava às portas: Se via escudo ou lança Entre quarenta mil em Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 9, 'Meu coração está pelos líderes de Israel, Os que com boa vontade se ofereceram entre o povo: Louvai ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 10, 'Vós os que cavalgais em asnas brancas, Os que presidis em juízo, E vós os que viajais, falai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 11, 'Longe do ruído dos arqueiros, nos bebedouros, Ali repetirão as justiças do SENHOR, As justiças de suas vilas em Israel; Então o povo do SENHOR desceu às portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 12, 'Desperta, desperta, Débora; Desperta, desperta, profere um cântico. Levanta-te, Baraque, e leva teus cativos, filho de Abinoão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 13, 'Então fez que o que restou do povo, senhoreie aos poderosos: o SENHOR me fez senhorear sobre os fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 14, 'De Efraim saiu sua raiz contra Amaleque, Depois ti, Benjamim, contra teus povos; De Maquir desceram príncipes, E de Zebulom os que costumavam manejar vara de oficial.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 15, 'Príncipes também de Issacar foram com Débora; E como Issacar, também Baraque Se pôs a pé no vale. Das divisões de Rúben houve grandes impressões do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 16, 'Por que te restaste entre os currais, Para ouvir os balidos dos rebanhos? Das divisões de Rúben Grandes foram os questionamentos do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 17, 'Gileade se restou da outra parte do Jordão: E Dã por que se esteve junto aos navios? Manteve-se Aser à beira do mar, E ficou em seus portos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 18, 'O povo de Zebulom expôs sua vida à morte, E Naftali nas alturas do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 19, 'Vieram reis e lutaram: Então lutaram os reis de Canaã Em Taanaque, junto às águas de Megido, Mas não levaram despojo algum de dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 20, 'Dos céus lutaram: As estrelas desde suas órbitas lutaram contra Sísera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 21, 'Varreu-os o ribeiro de Quisom, O antigo ribeiro, o ribeiro de Quisom. Pisaste, ó alma minha, com força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 22, 'Espancaram-se então os cascos dos cavalos pelas arremetidas, pelos galopes de seus fortes cavalos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 23, 'Amaldiçoai a Meroz, disse o anjo do SENHOR: Amaldiçoai severamente a seus moradores, Porque não vieram em socorro ao SENHOR, Em socorro ao SENHOR contra os fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 24, 'Bendita seja entre as mulheres Jael, Mulher de Héber queneu; Sobre as mulheres bendita seja na tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 25, 'Ele pediu água, e deu-lhe ela leite; Em taça de nobres lhe apresentou manteiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 26, 'Sua mão estendeu à estaca, E sua direita a marreta de trabalhadores; E golpeou a Sísera, feriu sua cabeça, esmagou e atravessou suas têmporas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 27, 'Caiu encurvado entre seus pés, ficou estendido: Entre seus pés caiu encurvado; Onde se encurvou, ali caiu morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 28, 'A mãe de Sísera olha à janela, E por entre as grades a vozes disse: Por que se detém seu carro, que não vem? Por que as rodas de seus carros se tardam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 29, 'As mais avisadas de suas damas lhe respondiam; E ainda ela se respondia a si mesma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 30, 'Não acharam despojos, e os estão repartindo? A cada um uma moça, ou duas: Os despojos de cores para Sísera, Os despojos bordados de cores: A roupa de cor bordada de ambos os lados, para os pescoços dos que tomaram os despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 5, 31, 'Assim pereçam todos os teus inimigos, ó SENHOR: Mas os que lhe amam, sejam como o sol quando nasce em sua força. E a terra repousou quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 1, 'Mas os filhos de Israel fizeram o mal aos olhos do SENHOR; e o SENHOR os entregou nas mãos de Midiã por sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 2, 'E a mão de Midiã prevaleceu contra Israel. E os filhos de Israel, por causa dos midianitas, se fizeram covas nos montes, e cavernas, e lugares fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 3, 'Pois quando os de Israel haviam semeado, subiam os midianitas, e amalequitas, e os orientais: subiam contra eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 4, 'E assentando acampamento contra eles destruíam os frutos da terra, até chegar a Gaza; e não deixavam o que comer em Israel, nem ovelhas, nem bois, nem asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 5, 'Porque subiam eles e seus gados, e vinham com suas tendas em grande multidão como gafanhotos, que não havia número neles nem em seus camelos: assim vinham à terra para devastá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 6, 'Era, pois, Israel em grande maneira empobrecido pelos midianitas; e os filhos de Israel clamaram ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 7, 'E quando os filhos de Israel clamaram ao SENHOR, por causa dos midianitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 8, 'O SENHOR enviou um homem profeta aos filhos de Israel, o qual lhes disse: Assim disse o SENHOR Deus de Israel: Eu vos fiz sair do Egito, e vos tirei da casa de servidão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 9, 'Eu vos livrei da mão dos egípcios, e da mão de todos os que vos afligiram, aos quais expulsei de diante de vós, e vos dei sua terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 10, 'E disse-vos: Eu sou o SENHOR vosso Deus; não temais aos deuses dos amorreus, em cuja terra habitais; mas não obedecestes à minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 11, 'E veio o anjo do SENHOR, e sentou-se debaixo do carvalho que está em Ofra, o qual era de Joás abiezrita; e seu filho Gideão estava malhando o trigo na prensa de uvas, para fazê-lo esconder dos midianitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 12, 'E o anjo do SENHOR se lhe apareceu, e disse-lhe: O SENHOR é contigo, homem esforçado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 13, 'E Gideão lhe respondeu: Ah, Senhor meu, se o SENHOR é conosco, por que nos sobreveio tudo isto? E onde estão todas suas maravilhas, que nossos pais nos contaram, dizendo: Não nos tirou o SENHOR do Egito? E agora o SENHOR nos desamparou, e nos entregou nas mãos dos midianitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 14, 'E olhando-lhe o SENHOR, disse-lhe: Vai com esta tua força, e salvarás a Israel da mão dos midianitas. Não te envio eu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 15, 'Então lhe respondeu: Ah, Senhor meu, com que tenho de salvar a Israel? Eis que minha família é pobre em Manassés, e eu o menor na casa de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 16, 'E o SENHOR lhe disse: Porque eu serei contigo, e ferirás aos midianitas como a um só homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 17, 'E ele respondeu: Eu te rogo que, se achei favor diante de ti, me dês sinal de que tu falaste comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 18, 'Rogo-te que não te vás daqui, até que eu volte a ti, e traga a minha oferta, e a ponha diante de ti. E ele respondeu: Eu esperarei até que voltes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 19, 'E entrando-se Gideão preparou um cabrito, e pães sem levedura de um efa de farinha; e pôs a carne em um cesto, e o caldo em uma caçarola, e tirando-o apresentou-lhe debaixo daquele carvalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 20, 'E o anjo de Deus lhe disse: Toma a carne, e os pães sem levedura, e põe-o sobre esta penha, e derrama o caldo. E ele o fez assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 21, 'E estendendo o anjo do SENHOR o bordão que tinha em sua mão, tocou com a ponta na carne e nos pães sem levedura; e subiu fogo da penha, o qual consumiu a carne e os pães sem levedura. E o anjo do SENHOR desapareceu de diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 22, 'E vendo Gideão que era o anjo do SENHOR, disse: Ah, Senhor DEUS, que vi o anjo do SENHOR face a face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 23, 'E o SENHOR lhe disse: Paz seja contigo; não tenhas medo, não morrerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 24, 'E edificou ali Gideão altar ao SENHOR, ao que chamou O SENHOR é paz: está até hoje em Ofra dos abiezritas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 25, 'E aconteceu que a mesma noite lhe disse o SENHOR: Toma um touro do rebanho de teu pai, e outro touro de sete anos, e derruba o altar de Baal que teu pai tem, e corta também o bosque que está junto a ele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 26, 'E edifica altar ao SENHOR teu Deus no cume deste penhasco em lugar conveniente; e tomando o segundo touro, sacrifica-o em holocausto sobre a lenha do bosque que haverás cortado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 27, 'Então Gideão tomou dez homens de seus servos, e fez como o SENHOR lhe disse. Mas temendo fazê-lo de dia, pela família de seu pai e pelos homens da cidade, o fez de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 28, 'E à manhã, quando os da cidade se levantaram, eis que o altar de Baal estava derrubado, e cortado o bosque que junto a ele estava, e sacrificado aquele segundo touro em holocausto sobre o altar edificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 29, 'E diziam-se uns aos outros: Quem fez isto? E buscando e investigando, disseram-lhes: Gideão filho de Joás o fez. Então os homens da cidade disseram a Joás:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 30, 'Tira fora teu filho para que morra, porquanto derrubou o altar de Baal e cortou o bosque que junto a ele estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 31, 'E Joás respondeu a todos os que estavam junto a ele: Tomareis vós a demanda por Baal? Vós o salvareis? Qualquer um que tomar a demanda por ele, que morra amanhã. Se é Deus, contenda por si mesmo com o que derrubou seu altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 32, 'E aquele dia ele chamou a Gideão Jerubaal; porque disse: Pleiteie Baal contra o que derrubou seu altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 33, 'E todos os midianitas, e amalequitas, e orientais, se juntaram de uma vez, e passando assentaram acampamento no vale de Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 34, 'E o espírito do SENHOR se investiu em Gideão, e quando este tocou a a trombeta, Abiezer se juntou com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 35, 'E enviou mensageiros por todo Manassés, o qual também se juntou com ele: também enviou mensageiros a Aser, e a Zebulom, e a Naftali, os quais saíram a encontrar-lhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 36, 'E Gideão disse a Deus: Se hás de salvar a Israel por minha mão, como disseste,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 37, 'Eis que eu porei um velo de lã na era; e se o orvalho estiver no velo somente, restando seca toda a outra terra, então entenderei que hás de salvar a Israel por minha mão, como o disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 38, 'E aconteceu assim: porque quando se levantou de manhã, espremendo o velo tirou dele o orvalho, um vaso cheio de água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 39, 'Mas Gideão disse a Deus: Não se acenda tua ira contra mim, se ainda falar esta vez: somente provarei agora outra vez com o velo. Rogo-te que a secura seja somente no velo, e o orvalho sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 6, 40, 'E aquela noite o fez Deus assim: porque a secura foi somente no velo, e em toda a terra esteve o orvalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 1, 'Levantando-se, pois, de manhã Jerubaal, o qual é Gideão, e todo aquele povo que estava com ele, assentaram o acampamento junto à fonte de Harode: e tinha o acampamento dos midianitas ao norte, da outra parte do morro de Moré, no vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 2, 'E o SENHOR disse a Gideão: O povo que está contigo é muito para que eu dê aos midianitas em sua mão: para que não se glorie Israel contra mim, dizendo: Minha mão me salvou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 3, 'Agora, pois, proclama aos ouvidos do povo, dizendo: Aquele que teme e se estremece, volte e retire-se do monte de Gileade. E do povo voltaram vinte e dois mil; e restaram dez mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 4, 'E o SENHOR disse a Gideão: Ainda é muito o povo; leva-os às águas, e ali eu te os provarei; e do que eu te disser: Vá este contigo, vá contigo: mas de qualquer um que eu te disser: Este não vá contigo, o tal não vá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 5, 'Então levou o povo às águas: e o SENHOR disse a Gideão: Qualquer um que lamber as águas com sua língua como lambe o cão, aquele porás à parte; também qualquer um que se dobrar sobre seus joelhos para beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 6, 'E foi o número dos que lamberam as águas, achegando-a com a mão à boca, trezentos homens: e todo aquele resto do povo se dobrou sobre seus joelhos para beber as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 7, 'Então o SENHOR disse a Gideão: Com estes trezentos homens que lamberam o água vos salvarei, e entregarei aos midianitas em tuas mãos; e vá-se todo o resto do povo cada um a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 8, 'Depois de tomarem a provisão do povo e suas trombetas, ele enviou todos os israelitas cada um a sua tenda, mas manteve aqueles trezentos homens; e o campo de Midiã estava no vale abaixo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 9, 'E aconteceu que aquela noite o SENHOR lhe disse: Levanta-te, e desce ao acampamento; porque eu o entreguei em tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 10, 'E se temes descer para atacar, desce apenas tu e o teu servo Pura ao acampamento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 11, 'e ouvirás o que falam; e então tuas mãos se fortalecerão, e descerás para atacar o acampamento. E ele desceu com o seu servo Pura à extremidade dos homens armados que estavam no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 12, 'E Midiã, e Amaleque, e todos os orientais, estavam estendidos no vale como gafanhotos em multidão, e seus camelos eram inúmeros, como a areia que está à beira do mar em multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 13, 'E logo que chegou Gideão, eis que um homem estava contando a seu companheiro um sonho, dizendo: Eis que eu sonhei um sonho: que via um pão de cevada que rodava até o acampamento de Midiã, e chegava às tendas, e as feria de tal maneira que caíam, e as virava de cima abaixo, e as tendas caíam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 14, 'E seu companheiro respondeu, e disse: Isto não é outra coisa a não ser a espada de Gideão filho de Joás, homem de Israel: Deus entregou em suas mãos aos midianitas com todo o acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 15, 'E quando Gideão ouviu a história do sonho e sua interpretação, adorou; e voltado ao acampamento de Israel, disse: Levantai-vos, que o SENHOR entregou o acampamento de Midiã em vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 16, 'E repartindo os trezentos homens em três esquadrões, deu a cada um deles trombetas em suas mãos, e cântaros vazios com tochas ardendo dentro dos cântaros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 17, 'E disse-lhes: Olhai a mim, e fazei como eu fizer; eis que quando eu chegar ao princípio do acampamento, como eu fizer, assim fareis vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 18, 'Eu tocarei a trombeta e todos os que estiverem comigo; e vós tocareis então as trombetas ao redor de todo aquele campo, e direis: Pelo SENHOR e Gideão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 19, 'Chegou, pois, Gideão, e os cem homens que levava consigo, ao princípio do acampamento, à entrada da vigília do meio, quando acabavam de renovar as sentinelas; e tocaram as trombetas, e quebraram os cântaros que levavam em suas mãos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 20, 'E os três esquadrões tocaram as trombetas, e quebrando os cântaros tomaram nas mãos esquerdas as tochas, e nas direitas as trombetas com que tocavam, e deram grito: A espada do SENHOR e de Gideão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 21, 'E estiveram em seus lugares em derredor do acampamento: e todo aquele acampamento foi alvoroçado, e fugiram gritando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 22, 'Mas os trezentos tocavam as trombetas: e o SENHOR pôs a espada de cada um contra seu companheiro em todo aquele acampamento. E o exército fugiu até Bete-Sita, até Zererá, e até o termo de Abel-Meolá em Tabate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 23, 'E juntando-se os de Israel, de Naftali, e de Aser, e de todo Manassés, seguiram aos midianitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 24, 'Gideão também enviou mensageiros a todo aquele monte de Efraim, dizendo: Descei ao encontro dos midianitas, e tomai-lhes as águas até Bete-Bara e o Jordão. E juntos todos os homens de Efraim, tomaram as águas de Bete-Bara e o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 7, 25, 'E tomaram dois príncipes dos midianitas, Orebe e Zeebe: e mataram a Orebe na penha de Orebe, e a Zeebe o mataram na prensa de uvas de Zeebe; e depois que seguiram aos midianitas, trouxeram as cabeças de Orebe e de Zeebe a Gideão da outra parte do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 1, 'E os de Efraim lhe disseram: Que é isto que fizeste conosco, não chamando-nos quando ias à guerra contra Midiã? E reclamaram dele fortemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 2, 'Aos quais ele respondeu: Que fiz eu agora como vós? Não são as sobras das uvas de Efraim melhor que a vindima de Abiezer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 3, 'Deus entregou em vossas mãos a Orebe e a Zeebe, príncipes de Midiã: e que pude eu fazer como vós? Então a ira deles contra ele se aplacou, logo que ele falou esta palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 4, 'E veio Gideão ao Jordão para passar, ele e os trezentos homens que trazia consigo, cansados, mas ainda perseguindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 5, 'E disse aos de Sucote: Eu vos rogo que deis à gente que me segue alguns bocados de pão; porque estão cansados, e eu persigo a Zeba e a Zalmuna, reis de Midiã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 6, 'E os principais de Sucote responderam: Está já a mão de Zeba e Zalmuna em tua mão, para que havemos nós de dar pão a teu exército?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 7, 'E Gideão disse: Pois quando o SENHOR entregar em minha mão a Zeba e a Zalmuna, eu trilharei vossa carne com espinhos e cardos do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 8, 'E dali subiu a Peniel, e falou-lhes as mesmas palavras. E os de Peniel lhe responderam como haviam respondido os de Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 9, 'E ele falou também aos de Peniel, dizendo: Quando eu voltar em paz, derrubarei esta torre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 10, 'E Zeba e Zalmuna estavam em Carcor, e com eles seu exército de como quinze mil homens, todos os que haviam restado de todo aquele acampamento dos orientais: e os mortos haviam sido cento vinte mil homens que tiravam espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 11, 'E subindo Gideão até os que habitavam em tendas, à parte oriental de Noba e de Jogbeá, feriu o acampamento, porque estava o exército desprevenido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 12, 'E fugindo Zeba e Zalmuna, ele os seguiu; e tomados os dois reis de Midiã, Zeba e Zalmuna, espantou a todo aquele exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 13, 'E Gideão filho de Joás voltou da batalha antes que o sol subisse;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 14, 'E tomou um jovem dos de Sucote, e perguntando-lhe, ele lhe deu por escrito os principais de Sucote e seus anciãos, setenta e sete homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 15, 'E entrando aos de Sucote, disse: Eis aqui a Zeba e a Zalmuna, sobre os quais me escarnecestes, dizendo: Está já a mão de Zeba e de Zalmuna em tua mão, para que demos nós pão a teus homens cansados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 16, 'E tomou aos anciãos da cidade, e espinhos e cardos do deserto, e castigou com eles aos de Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 17, 'Também derrubou a torre de Peniel, e matou aos da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 18, 'Logo disse a Zeba e a Zalmuna: Que maneira de homens tinham aqueles que matastes em Tabor? E eles responderam: Como tu, tais eram aqueles nem mais nem menos, que apareciam filhos de rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 19, 'E ele disse: Meus irmãos eram, filhos de minha mãe: Vive o SENHOR, que se os tivésseis guardado em vida, eu não vos mataria!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 20, 'E disse a Jéter seu primogênito: Levanta-te, e mata-os. Mas o jovem não desembainhou sua espada, porque tinha medo; que ainda era jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 21, 'Então disse Zeba e Zalmuna: Levanta-te tu, e mata-nos; porque como é o homem, tal é sua valentia. E Gideão se levantou, e matou a Zeba e a Zalmuna; e tomou os adornos de crescentes que seus camelos traziam ao pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 22, 'E os israelitas disseram a Gideão: Sê nosso senhor, tu, e teu filho, e teu neto; pois que nos livraste da mão de Midiã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 23, 'Mas Gideão respondeu: Não serei senhor sobre vós, nem meu filho vos dominará: o SENHOR será vosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 24, 'E disse-lhes Gideão: Desejo fazer-vos uma petição, que cada um me dê os pendentes de seu despojo. (Porque traziam pendentes de ouro, que eram ismaelitas.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 25, 'E eles responderam: De boa vontade os daremos. E segurando uma roupa de vestir, lançou ali cada um os pendentes de seu despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 26, 'E foi o peso dos pendentes de ouro que ele pediu mil e setecentos siclos de ouro; sem contar os ornamentos, e as joias, e vestidos de púrpura, que traziam os reis de Midiã, e sem os colares que traziam seus camelos ao pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 27, 'E Gideão fez deles um éfode, o qual fez guardar em sua cidade de Ofra: e todo Israel prostituiu-se atrás desse éfode naquele lugar; e foi por tropeço a Gideão e a sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 28, 'Assim foi humilhado Midiã diante dos filhos de Israel, e nunca mais levantaram sua cabeça. E repousou a terra quarenta anos nos dias de Gideão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 29, 'E Jerubaal filho de Joás foi, e habitou em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 30, 'E teve Gideão setenta filhos que saíram de sua coxa, porque teve muitas mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 31, 'E sua concubina que estava em Siquém, também lhe deu um filho; e pôs-lhe por nome Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 32, 'E morreu Gideão filho de Joás em boa velhice, e foi sepultado no sepulcro de seu pai Joás, em Ofra dos abiezritas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 33, 'E aconteceu que quando morreu Gideão, os filhos de Israel voltaram, e se prostituíram atrás dos baalins, e se puseram por Deus a Baal-Berite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 34, 'E os filhos de Israel não se lembraram do SENHOR seu Deus, que os havia livrado de todos os seus inimigos ao redor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 8, 35, 'Nem fizeram misericórdia com a casa de Jerubaal Gideão conforme todo aquele bem que ele havia feito a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 1, 'E foi-se Abimeleque filho de Jerubaal a Siquém, aos irmãos de sua mãe, e falou com eles, e com toda a família da casa do pai de sua mãe, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 2, 'Eu vos rogo que faleis a ouvidos de todos os de Siquém: Que tendes por melhor, que vos dominem setenta homens, todos os filhos de Jerubaal; ou que vos senhoreie um homem? Lembrai-vos que eu sou osso vosso, e carne vossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 3, 'E falaram por ele os irmãos de sua mãe a ouvidos de todos os de Siquém todas estas palavras: e o coração deles se inclinou em favor de Abimeleque, porque diziam: Nosso irmão é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 4, 'E deram-lhe setenta siclos de prata do templo de Baal-Berite, com os quais Abimeleque contratou homens ociosos e vagabundos, que lhe seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 5, 'E vindo à casa de seu pai em Ofra, matou a seus irmãos os filhos de Jerubaal, setenta homens, sobre uma pedra: mas restou Jotão, o menor filho de Jerubaal, que se escondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 6, 'E reunidos todos os de Siquém com toda a casa de Milo, foram e elegeram a Abimeleque por rei, próximo da planície do pilar que estava em Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 7, 'E quando se o disseram a Jotão, foi e pôs-se no cume do monte de Gerizim, e levantando sua voz clamou, e disse-lhes: Ouvi-me, homens de Siquém; que Deus vos ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 8, 'Foram as árvores a eleger rei sobre si, e disseram à oliva: Reina sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 9, 'Mas a oliveira respondeu: Tenho de deixar meu azeite, com o que por minha causa Deus e os homens são honrados, para ir a ser grande sobre as árvores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 10, 'E disseram as árvores à figueira: Anda tu, reina sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 11, 'E respondeu a figueira: Tenho de deixar minha doçura e meu bom fruto, para ir a ser grande sobre as árvores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 12, 'Disseram logo as árvores à vide: Pois vem tu, reina sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 13, 'E a vide lhes respondeu: Tenho de deixar meu mosto, que alegra a Deus e aos homens, para ir a ser grande sobre as árvores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 14, 'Disseram então todas as árvores ao espinheiro: Vem tu, reina sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 15, 'E o espinheiro respondeu às árvores: Se em verdade me elegeis por rei sobre vós, vinde, e assegurai-vos debaixo de minha sombra: e se não, fogo saia do espinheiro que devore os cedros do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 16, 'Agora, pois, se com verdade e com integridade tendes procedido em fazer rei a Abimeleque, e se o fizestes bem com Jerubaal e com sua casa, e se lhe haveis pagado conforme a obra de suas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 17, '(Pois que meu pai lutou por vós, e expulsou longe sua vida para livrar-vos da mão de Midiã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 18, 'E vós vos levantastes hoje contra a casa de meu pai, e matastes seus filhos, setenta homens, sobre uma pedra; e pusestes por rei sobre os de Siquém a Abimeleque, filho de sua criada, porquanto é vosso irmão);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 19, 'Se com verdade e com integridade agistes hoje com Jerubaal e com sua casa, alegrai-vos de Abimeleque, e ele se alegre de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 20, 'E se não, fogo saia de Abimeleque, que consuma aos de Siquém e à casa de Milo; e fogo saia dos de Siquém e da casa de Milo, que consuma a Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 21, 'E fugiu Jotão, e se escapou, e foi-se a Beer, e ali se esteve por causa de Abimeleque seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 22, 'E depois que Abimeleque dominou sobre Israel três anos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 23, 'Enviou Deus um espírito mau entre Abimeleque e os homens de Siquém: que os de Siquém se levantaram contra Abimeleque:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 24, 'Para que o crime dos setenta filhos de Jerubaal, e o sangue deles, viesse a se pôr sobre Abimeleque seu irmão que os matou, e sobre os homens de Siquém que corroboraram as mãos dele para matar a seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 25, 'E puseram-lhe os de Siquém emboscadores nos cumes dos montes, os quais assaltavam a todos os que passavam junto a eles pelo caminho; do que foi dado aviso a Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 26, 'E Gaal filho de Ebede veio com seus irmãos, e passaram a Siquém: e os de Siquém se confiaram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 27, 'E saindo ao campo, vindimaram suas vinhas, e pisaram a uva, e fizeram alegrias; e entrando no templo de seus deuses, comeram e beberam, e amaldiçoaram a Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 28, 'E Gaal filho de Ebede disse: Quem é Abimeleque e que é Siquém, para que nós a ele sirvamos? não é filho de Jerubaal? e não é Zebul seu assistente? Servi aos homens de Hamor pai de Siquém: mas por que serviríamos a ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 29, 'Fosse-me dado este povo abaixo de minha mão, eu expulsaria logo a Abimeleque. E dizia a Abimeleque: Aumenta teus esquadrões, e sai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 30, 'E Zebul assistente da cidade, ouvindo as palavras de Gaal filho de Ebede, acendeu-se sua ira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 31, 'E enviou sagazmente mensageiros a Abimeleque, dizendo: Eis que Gaal filho de Ebede e seus irmãos vieram a Siquém, e eis que cercaram a cidade contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 32, 'Levanta-te, pois, agora de noite, tu e o povo que está contigo, e põe emboscada no campo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 33, 'E pela manhã ao sair do sol te levantarás e atacarás a cidade: e ele e o povo que está com ele sairão contra ti, e tu farás com ele segundo que se te oferecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 34, 'Levantando-se, pois, de noite Abimeleque e todo aquele povo que com ele estava, puseram emboscada contra Siquém com quatro companhias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 35, 'E Gaal filho de Ebede saiu, e pôs-se à entrada da porta da cidade: e Abimeleque e todo aquele povo que com ele estava, se levantaram da emboscada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 36, 'E vendo Gaal o povo, disse a Zebul: Eis ali povo que desce dos cumes dos montes. E Zebul lhe respondeu: A sombra dos montes te parece homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 37, 'Mas Gaal voltou a falar, e disse: Eis ali um povo que desce por meio da terra, e um esquadrão vem pelo caminho da campina de Meonenim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 38, 'E Zebul lhe respondeu: Onde está agora aquele teu falar, dizendo; Quem é Abimeleque para que lhe sirvamos? Não é este o povo que menosprezavas? Sai, pois, agora, e luta com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 39, 'E Gaal saiu diante dos de Siquém, e lutou contra Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 40, 'Mas perseguiu-o Abimeleque, diante do qual ele fugiu; e caíram feridos muitos até a entrada da porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 41, 'E Abimeleque ficou em Aruma; e Zebul lançou fora a Gaal e a seus irmãos, para que não morassem em Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 42, 'E aconteceu ao dia seguinte, que o povo saiu ao campo: e foi dado aviso a Abimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 43, 'O qual, tomando gente, repartiu-a em três companhias, e pôs emboscadas no campo: e quando olhou, eis o povo que saía da cidade; e levantou-se contra eles, e feriu-os:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 44, 'Pois Abimeleque e o esquadrão que estava com ele, atacaram com ímpeto, e pararam à entrada da porta da cidade; e as duas companhias atacaram a todos os que estavam no campo, e os feriram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 45, 'E depois de combater Abimeleque a cidade todo aquele dia, tomou-a, e matou o povo que nela estava, e assolou a cidade, e semeou-a de sal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 46, 'Quando ouviram isto todos os que estavam na torre de Siquém, entraram na fortaleza do templo do deus Berite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 47, 'E foi dito a Abimeleque como todos os da torre de Siquém estavam reunidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 48, 'Então subiu Abimeleque ao monte de Salmom, ele e toda a gente que com ele estava; e tomou Abimeleque um machado em sua mão, e cortou um ramo das árvores, levantou-o, e o pôs sobre seus ombros, dizendo ao povo que estava com ele: O que vós vedes que estou fazendo, fazei imediatamente como eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 49, 'E assim todo aquele povo cortou também cada um seu ramo, e seguiram a Abimeleque, e puseram-nas junto à fortaleza, e prenderam fogo com elas à fortaleza: por maneira que todos os da torre de Siquém morreram, como uns mil homens e mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 50, 'Depois Abimeleque se foi a Tebes; e pôs cerco a Tebes, e tomou-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 51, 'Em meio daquela cidade havia uma torre forte, à qual se retiraram todos os homens e mulheres, e todos os senhores da cidade; e fechando atrás de si as portas, subiram ao piso alto da torre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 52, 'E veio Abimeleque à torre, e combatendo-a, chegou-se à porta da torre para pegar-lhe fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 53, 'Mas uma mulher deixou cair um pedaço de uma roda de moinho sobre a cabeça de Abimeleque, e quebrou-lhe o crânio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 54, 'E logo ele chamou a seu escudeiro, e disse-lhe: Tira tua espada e mata-me, porque não se diga de mim: Uma mulher o matou. E seu escudeiro o atravessou, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 55, 'E quando os israelitas viram morto a Abimeleque, foram-se cada um à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 56, 'Assim, pois, Deus pagou a Abimeleque o mal que fez contra seu pai matando a seus setenta irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 9, 57, 'E ainda todo aquele mal dos homens de Siquém devolveu Deus sobre suas cabeças: e a maldição de Jotão, filho de Jerubaal, veio sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 1, 'E Depois de Abimeleque levantou-se para livrar a Israel, Tolá filho de Puá, filho de Dodô, homem de Issacar, o qual habitava em Samir, no monte de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 2, 'E julgou a Israel vinte e três anos, e morreu, e foi sepultado em Samir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 3, 'Depois dele se levantou Jair, gileadita, o qual julgou a Israel vinte e dois anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 4, 'Este teve trinta filhos que cavalgavam sobre trinta asnos, e tinham trinta vilas, que se chamaram as vilas de Jair até hoje, as quais estão na terra de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 5, 'E morreu Jair, e foi sepultado em Camom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 6, 'Mas os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR, e serviram aos baalins e a Astarote, e aos deuses da Síria, e aos deuses de Sidom, e aos deuses de Moabe, e aos deuses dos filhos de Amom, e aos deuses dos filisteus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 7, 'E o SENHOR se irou contra Israel, e vendeu-os por mão dos filisteus, e por mão dos filhos de Amom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 8, 'Os quais moeram e quebrantaram aos filhos de Israel naquele tempo dezoito anos, a todos os filhos de Israel que estavam da outra parte do Jordão na terra dos amorreus, que é em Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 9, 'E os filhos de Amom passaram o Jordão para fazer também guerra contra Judá, e contra Benjamim, e a casa de Efraim: e foi Israel em grande maneira afligido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 10, 'E os filhos de Israel clamaram ao SENHOR, dizendo: Nós pecamos contra ti; porque deixamos a nosso Deus, e servido aos baalins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 11, 'E o SENHOR respondeu aos filhos de Israel: Não fostes oprimidos pelo Egito, pelos amorreus, pelos amonitas, dos filisteus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 12, 'Dos de Sidom, de Amaleque, e de Maom, e clamando a mim vos livrei de suas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 13, 'Mas vós me deixastes, e servistes a deuses alheios: portanto, eu não vos livrarei mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 14, 'Andai, e clamai aos deuses que escolhestes para vós, que vos livrem no tempo de vossa aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 15, 'E os filhos de Israel responderam ao SENHOR: Pecamos; faze tu conosco como bem te parecer: somente que agora nos livres neste dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 16, 'E tiraram dentre si os deuses alheios, e serviram ao SENHOR; e sua alma foi angustiada por causa do sofrimento de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 17, 'E juntando-se os filhos de Amom, assentaram acampamento em Gileade; juntaram-se assim os filhos de Israel, e assentaram seu acampamento em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 10, 18, 'E os príncipes e o povo de Gileade disseram um ao outro: Quem será o que começará a batalha contra os filhos de Amom? Ele será cabeça sobre todos os que habitam em Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 1, 'Existia então Jefté, gileadita, homem valente, filho de uma prostituta, ao qual havia gerado Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 2, 'E a mulher de Gileade também lhe havia dado à luz filhos; os quais quando foram grandes, lançaram fora a Jefté, dizendo-lhe: Não herdarás na casa de nosso pai, porque és bastardo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 3, 'Fugindo, pois, Jefté por causa de seus irmãos, habitou em terra de Tobe; e juntaram-se com ele homens ociosos, os quais com ele saíam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 4, 'E aconteceu que depois de dias os filhos de Amom fizeram guerra contra Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 5, 'E quando os filhos de Amom tinham guerra contra Israel, os anciãos de Gileade foram para fazer voltar a Jefté da terra de Tobe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 6, 'E disseram a Jefté: Vem, e serás nosso capitão, para que lutemos com os filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 7, 'E Jefté respondeu aos anciãos de Gileade: Não me odiastes, e me lançastes da casa de meu pai? por que pois vindes agora a mim quando estais em aflição?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 8, 'E os anciãos de Gileade responderam a Jefté: Por esta mesma causa voltamos agora a ti, para que venhas conosco, e lutes contra os filhos de Amom, e nos sejas cabeça a todos os que moramos em Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 9, 'Jefté então disse aos anciãos de Gileade: Se me fazeis voltar para que lute contra os filhos de Amom, e o SENHOR os entregar diante de mim, serei eu vossa cabeça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 10, 'E os anciãos de Gileade responderam a Jefté: O SENHOR ouça entre nós, se não fizermos como tu dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 11, 'Então Jefté veio com os anciãos de Gileade, e o povo o elegeu por seu cabeça e príncipe; e Jefté falou todas seus palavras diante do SENHOR em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 12, 'E enviou Jefté embaixadores ao rei dos amonitas, dizendo: Que tens tu comigo que vieste a mim para fazer guerra em minha terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 13, 'E o rei dos amonitas respondeu aos embaixadores de Jefté: Porquanto Israel tomou minha terra, quando subiu do Egito, desde Arnom até Jaboque e o Jordão; portanto, devolve-as agora em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 14, 'E Jefté voltou a enviar outros embaixadores ao rei dos amonitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 15, 'Para dizer-lhe: Jefté disse assim: Israel não tomou terra de Moabe, nem terra dos filhos de Amom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 16, 'Mas subindo Israel do Egito, andou pelo deserto até o mar Vermelho, e chegou a Cades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 17, 'Então Israel enviou embaixadores ao rei de Edom, dizendo: Eu te rogo que me deixes passar por tua terra. Mas o rei de Edom não os escutou. Enviou também ao rei de Moabe; o qual tampouco quis: ficou, portanto, Israel em Cades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 18, 'Depois, indo pelo deserto, rodeou a terra de Edom e a terra de Moabe, e vindo pelo lado oriental da terra de Moabe, assentou seu acampamento de outra parte de Arnom, e não entraram pelo termo de Moabe: porque Arnom é termo de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 19, 'E enviou Israel embaixadores a Seom rei pelos amorreus, rei de Hesbom, dizendo-lhe: Rogo-te que me deixes passar por tua terra até meu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 20, 'Mas Seom não confiou em Israel para dar-lhe passagem por seu termo; antes juntando Seom toda sua gente, pôs acampamento em Jaza, e lutou contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 21, 'Porém o SENHOR, o Deus de Israel, entregou Seom e todo o seu povo na mão de Israel, e os derrotou; e Israel tomou posse de toda a terra dos amorreus que habitavam naquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 22, 'Possuíram também todo aquele termo dos amorreus desde Arnom até Jaboque, e desde o deserto até o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 23, 'Assim que o SENHOR o Deus de Israel expulsou os amorreus diante de seu povo Israel: e o hás de possuir tu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 24, 'Se Camos teu Deus te expulsasse algum, não o possuirias tu? Assim nós possuiremos a tudo aquilo que o SENHOR expulsou nosso Deus de diante de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 25, 'És tu agora em algo melhor que Balaque filho de Zipor, rei de Moabe? Teve ele questão contra Israel, ou fez guerra contra eles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 26, 'Quando Israel esteve habitando por trezentos anos a Hesbom e suas aldeias, a Aroer e suas aldeias, e todas as cidades que estão aos termos de Arnom, por que não as reclamaste nesse tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 27, 'Assim que, eu nada pequei contra ti, mas tu fazes mal comigo fazendo-me guerra: o SENHOR, que é o juiz, julgue hoje entre os filhos de Israel e os filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 28, 'Mas o rei dos filhos de Amom não atendeu os argumentos de Jefté que lhe enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 29, 'E o espírito do SENHOR foi sobre Jefté: e passou por Gileade e Manassés; e dali passou a Mispá de Gileade; e de Mispá de Gileade passou aos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 30, 'E Jefté fez voto ao SENHOR, dizendo: Se entregares aos amonitas em minhas mãos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 31, 'Qualquer um que me sair a receber das portas de minha casa, quando voltar dos amonitas em paz, será do SENHOR, e lhe oferecerei em holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 32, 'Passou, pois, Jefté aos filhos de Amom para lutar contra eles; e o SENHOR os entregou em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 33, 'E os feriu de grandíssimo dano desde Aroer até chegar a Minite, vinte cidades; e até a Abel-Queramim. Assim foram dominados os amonitas diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 34, 'E voltando Jefté a Mispá à sua casa, eis que sua filha lhe saiu a receber com adufes e danças, e era a única, a única sua; não tinha além dela outro filho nem filha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 35, 'E quando ele a viu, rompeu suas roupas dizendo: Ai, filha minha! De verdade me abateste, e tu és dos que me afligem: porque eu abri minha boca ao SENHOR, e não poderei retratar-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 36, 'Ela então lhe respondeu: Pai meu, se abriste tua boca ao SENHOR, faze de mim como saiu de tua boca, pois que o SENHOR fez vingança em teus inimigos os filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 37, 'E voltou a dizer a seu pai: Faze-me isto: deixa-me por dois meses que vá e desça pelos montes, e chore minha virgindade, eu e minhas companheiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 38, 'Ele então disse: Vai. E deixou-a por dois meses. E ela foi com suas companheiras, e chorou sua virgindade pelos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 39, 'Passados os dois meses, voltou a seu pai, e fez dela conforme seu voto que havia feito. E ela nunca conheceu homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 11, 40, 'De aqui foi o costume em Israel que de ano em ano iam as virgens de Israel a lamentar à filha de Jefté gileadita, quatro dias no ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 1, 'E juntando-se os homens de Efraim, passaram até o norte, e disseram a Jefté: Por que foste a fazer guerra contra os filhos de Amom, e não nos chamaste para que fôssemos contigo? Nós queimaremos a fogo tua casa contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 2, 'E Jefté lhes respondeu: Eu tive, e meu povo, uma grande contenda com os filhos de Amom, e vos chamei, e não me defendestes de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 3, 'Vendo pois que não me defendíeis, pus minha alma em minha palma, e passei contra os filhos de Amom, e o SENHOR os entregou em minha mão: por que pois subistes hoje contra mim para lutar comigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 4, 'E juntando Jefté a todos os homens de Gileade, lutou contra Efraim; e os de Gileade feriram a Efraim, porque haviam dito: Vós sois fugitivos de Efraim, vós sois gileaditas entre Efraim e Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 5, 'E os gileaditas tomaram os vaus do Jordão a Efraim; e era que, quando algum dos de Efraim que havia fugido, dizia, passarei? Os de Gileade lhe perguntavam: És tu efraimita? Se ele respondia, Não;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 6, 'Então lhe diziam: Agora, pois, dize, Chibolete. E ele dizia, Sibolete; porque não podia pronunciar daquela sorte. Então lhe lançavam mão, e lhe degolavam junto aos vaus do Jordão. E morreram então dos de Efraim quarenta e dois mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 7, 'E Jefté julgou Israel por seis anos: logo morreu Jefté gileadita, e foi sepultado em uma das cidades de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 8, 'Depois dele julgou a Israel Ibsã de Belém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 9, 'O qual teve trinta filhos e trinta filhas, as quais casou fora, e tomou de fora trinta filhas para seus filhos: e julgou a Israel sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 10, 'E morreu Ibsã, e foi sepultado em Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 11, 'Depois dele julgou a Israel Elom, zebulonita, o qual julgou Israel por dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 12, 'E morreu Elom, zebulonita, e foi sepultado em Aijalom na terra de Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 13, 'Depois dele julgou a Israel Abdom filho de Hilel, piratonita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 14, 'Este teve quarenta filhos e trinta netos, que cavalgavam sobre setenta asnos: e julgou a Israel oito anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 12, 15, 'E morreu Abdom filho de Hilel, piratonita, e foi sepultado em Piratom, na terra de Efraim, no monte de Amaleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 1, 'E os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR; e o SENHOR os entregou por mão dos filisteus, por quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 2, 'E havia um homem de Zorá, da tribo de Dã, o qual se chamava Manoá; e sua mulher era estéril, que nunca havia dado à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 3, 'A esta mulher apareceu o anjo do SENHOR, e disse-lhe: Eis que tu és estéril, e não pariste: mas conceberás e darás à luz um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 4, 'Agora, pois, olha que agora não bebas vinho, nem bebida forte, nem comas coisa imunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 5, 'Porque tu te farás grávida, e darás à luz um filho: e não subirá navalha sobre sua cabeça, porque aquele menino será nazireu a Deus desde o ventre, e ele começará a salvar a Israel da mão dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 6, 'E a mulher veio e contou-o a seu marido, dizendo: Um homem de Deus veio a mim, cujo aspecto era como o aspecto de um anjo de Deus, terrível em grande maneira; e não lhe perguntei de onde nem quem era, nem tampouco ele me disse seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 7, 'E disse-me: Eis que tu conceberás, e darás à luz um filho: portanto, agora não bebas vinho, nem bebida forte, nem comas coisa imunda; porque este menino desde o ventre será nazireu a Deus até o dia de sua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 8, 'Então orou Manoá ao SENHOR, e disse: Ah, Senhor meu, eu te rogo que aquele homem de Deus que enviaste, torne agora a vir a nós, e nos ensine o que havemos de fazer com o menino que há de nascer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 9, 'E Deus ouviu a voz de Manoá: e o anjo de Deus voltou outra vez à mulher, estando ela no campo; mas seu marido Manoá não estava com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 10, 'E a mulher correu prontamente, e noticiou-o a seu marido, dizendo-lhe: Olha que se me apareceu aquele homem que veio a mim o outro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 11, 'E levantou-se Manoá, e seguiu a sua mulher; e assim que chegou ao homem, disse-lhe: És tu aquele homem que falaste à mulher? E ele disse: Eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 12, 'Então Manoá disse: Cumpra-se pois tua palavra. Que ordem se terá com o menino, e que deve?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 13, 'E o anjo do SENHOR respondeu a Manoá: A mulher se guardará de todas as coisas que eu lhe disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 14, 'Ela não comerá coisa que proceda da vide que dá vinho; não beberá vinho nem bebida forte, e não comerá coisa imunda: há de guardar tudo o que lhe mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 15, 'Então Manoá disse ao anjo do SENHOR: Rogo-te permitas que te detenhamos, e preparemos um cabrito que pôr diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 16, 'E o anjo do SENHOR respondeu a Manoá: Ainda que me detenhas não comerei de teu pão: mas se quiseres fazer holocausto, sacrifica-o ao SENHOR. E não sabia Manoá que aquele fosse anjo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 17, 'Então disse Manoá ao anjo do SENHOR: Como é teu nome, para que quando se cumprir tua palavra te honremos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 18, 'E o anjo do SENHOR respondeu: Por que perguntas por meu nome, que é oculto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 19, 'E Manoá tomou um cabrito das cabras e uma oferta de alimentos, e o sacrificou sobre uma rocha ao SENHOR; e o anjo fez algo sobrenatural à vista de Manoá e de sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 20, 'Porque aconteceu que, quando a chama subia do altar até o céu, o anjo do SENHOR subiu na chama do altar à vista de Manoá e de sua mulher, os quais se prostraram em terra sobre seus rostos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 21, 'E o anjo do SENHOR não voltou a aparecer a Manoá nem à sua mulher. Então conheceu Manoá que era o anjo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 22, 'E disse Manoá à sua mulher: Certamente morreremos, porque vimos a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 23, 'E sua mulher lhe respondeu: Se o SENHOR nos quisesse matar, não tomaria de nossas mãos o holocausto e a oferta de alimentos, nem nos teria mostrado todas estas coisas, nem em tal tempo nos haveria anunciado isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 24, 'E a mulher deu à luz um filho, e chamou-lhe por nome Sansão. E o menino creceu, e o SENHOR o abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 13, 25, 'E o espírito do SENHOR começou a manifestar-se nele nos acampamentos de Dã, entre Zorá e Estaol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 1, 'E descendo Sansão a Timna, viu em Timna uma mulher das filhas dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 2, 'E subiu, e declarou-o a seu pai e a sua mãe, dizendo: Eu vi em Timna uma mulher das filhas dos filisteus: rogo-vos que a deis a mim por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 3, 'E seu pai e sua mãe lhe disseram: Não há mulher entre as filhas de teus irmãos, nem em todo meu povo, para que vás tu a tomar mulher dos filisteus incircuncisos? E Sansão respondeu a seu pai: Toma-a a mim por mulher, porque esta agradou a meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 4, 'Mas seu pai e sua mãe não sabiam que isto vinha do SENHOR, e que ele buscava ocasião contra os filisteus: porque naquele tempo os filisteus dominavam sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 5, 'E Sansão desceu com seu pai e com sua mãe a Timna: e quando chegaram às vinhas de Timna, eis que um leão jovem que vinha bramando até ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 6, 'E o espírito do SENHOR caiu sobre ele, e despedaçou-o como quem despedaça um cabrito, sem ter nada em sua mão: e não deu a entender a seu pai nem a sua mãe o que havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 7, 'Veio, pois, e falou à mulher que havia agradado a Sansão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 8, 'E voltando depois de alguns dias para tomá-la, apartou-se para ver o corpo morto do leão, e eis que no corpo do leão um enxame de abelhas, e um favo de mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 9, 'E tomando-o em suas mãos, foi-se comendo-o pelo caminho: e chegado que houve a seu pai e a sua mãe, deu-lhes também a eles que comessem; mas não lhes revelou que havia tomado aquela mel do corpo do leão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 10, 'Veio, pois, seu pai à mulher, e Sansão fez ali banquete; porque assim costumavam fazer os rapazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 11, 'E quando eles o viram, tomaram trinta companheiros que estivessem com ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 12, 'Aos quais Sansão disse: Eu vos proporei agora um enigma, o qual se nos sete dias do banquete vós me declarardes e descobrirdes, eu vos darei trinta sábanas e trinta mudas de vestidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 13, 'Mas se não o souberes declarar a mim, vós me dareis as trinta mantas e as trinta mudas de vestidos. E eles responderam: Propõe-nos teu enigma, e o ouviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 14, 'Então lhes disse: Do comedor saiu comida, E do forte saiu doçura. E eles não puderam declarar-lhe o enigma em três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 15, 'E ao sétimo dia disseram à mulher de Sansão: Induz a teu marido a que nos declare este enigma, para que não te queimemos a ti e à casa de teu pai. Chamaste-nos aqui para possuir-nos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 16, 'E chorou a mulher de Sansão diante dele, e disse: Somente me aborreces e não me amas, pois que não me declaras o enigma que propuseste aos filhos de meu povo. E ele respondeu: Eis que nem a meu pai nem a minha mãe o declarei; e havia eu de declará-lo a ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 17, 'E ela chorou diante dele os sete dias que eles tiveram banquete: mas ao sétimo dia ele o declarou a ela, porque lhe constrangeu; e ela o declarou aos filhos de seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 18, 'E ao sétimo dia, antes que o sol se pusesse, os da cidade lhe disseram: Que coisa mais doce que o mel? E que coisa mais forte que o leão? Se não arásseis com minha novilha, Nunca teríeis descoberto meu enigma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 19, 'E o espírito do SENHOR caiu sobre ele, e desceu a Asquelom, e feriu trinta homens deles; e tomando seus despojos, deu as mudas de vestidos aos que haviam explicado o enigma: e acendido em ira foi-se à casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 14, 20, 'E a mulher de Sansão foi dada a seu companheiro, com o qual ele antes se acompanhava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 1, 'E aconteceu depois de dias, que no tempo da colheita do trigo, Sansão visitou à sua mulher com um cabrito, dizendo: Entrarei à minha mulher à câmara. Mas o pai dela não o deixou entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 2, 'E disse o pai dela: Persuadi-me que a aborrecias, e dei-a a teu companheiro. Mas sua irmã menor, não é mais bela que ela? Toma-a, pois, em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 3, 'E Sansão lhes respondeu: Eu serei sem culpa esta vez para com os filisteus, se mal lhes fizer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 4, 'E foi Sansão e agarrou trezentas raposas, e tomando tochas, e segurando aquelas pelas caudas, pôs entre cada duas caudas uma tocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 5, 'Depois, acendendo as tochas, lançou as raposas nas plantações dos filisteus, e queimou pilhas de cereais e cereais nos pés, e vinhas e olivais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 6, 'E disseram os filisteus: Quem fez isto? E foi-lhes dito: Sansão, o genro do timnateu, porque lhe tirou sua mulher e a deu a seu companheiro. E vieram os filisteus, e queimaram a fogo a ela e a seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 7, 'Então Sansão lhes disse: Assim o havíeis de fazer? Mas eu me vingarei de vós, e depois cessarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 8, 'E feriu-os perna e coxa com grande mortandade; e desceu, e ficou na caverna da penha de Etã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 9, 'E os filisteus subiram e puseram acampamento em Judá, e estenderam-se por Leí.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 10, 'E os homens de Judá lhes disseram: Por que subistes contra nós? E eles responderam: A prender a Sansão subimos, para fazer-lhe como ele nos fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 11, 'E vieram três mil homens de Judá à caverna da penha de Etã, e disseram a Sansão: Não sabes tu que os filisteus dominam sobre nós? Por que nos fizeste isto? E ele lhes respondeu: Eu lhes fiz como eles me fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 12, 'Eles então lhe disseram: Nós viemos para prender-te, e entregar-te em mão dos filisteus. E Sansão lhes respondeu: Jurai-me que vós não me matareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 13, 'E eles lhe responderam, dizendo: Não, somente te prenderemos, e te entregaremos em suas mãos; mas não te mataremos. Então lhe ataram com duas cordas novas, e fizeram-lhe vir da penha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 14, 'E assim que veio até Leí, os filisteus lhe saíram a receber com gritos de vitória: e o espírito do SENHOR caiu sobre ele, e as cordas que estavam em seus braços se tornaram como linho queimado com fogo, e as amarras se caíram de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 15, 'E achando uma queixada de asno fresca, estendeu a mão e tomou-a, e feriu com ela a mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 16, 'Então Sansão disse: Com a queixada de um asno, um amontoado, dois amontoados; Com a queixada de um asno feri mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 17, 'E acabando de falar, lançou de sua mão a queixada, e chamou a aquele lugar Ramate-Leí.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 18, 'E tendo grande sede, clamou logo ao SENHOR, e disse: Tu deste esta grande salvação por meio de teu servo: e morrerei eu agora de sede, e cairei em mão dos incircuncisos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 19, 'Então quebrou Deus uma cavidade em Leí, e saíram dali águas, e bebeu, e recuperou seu espírito, e reanimou-se. Portanto chamou seu nome daquele lugar, En-Hacoré, o qual é em Leí, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 15, 20, 'E julgou a Israel nos dias dos filisteus vinte anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 1, 'E foi Sansão a Gaza, e viu ali uma mulher prostituta, e se deitou com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 2, 'E foi dito aos de Gaza: Sansão veio aqui. E cercaram-no, e puseram-lhe espias toda aquela noite à porta da cidade: e estiveram calados toda aquela noite, dizendo: Até a luz da manhã; então o mataremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 3, 'Mas Sansão dormiu até a meia noite; e à meia noite se levantou, e tomando as portas da cidade com seus dois pilares e seu ferrolho, lançou-as ao ombro, e foi-se, e subiu-se com elas ao cume do monte que está diante de Hebrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 4, 'Depois disto aconteceu que se apaixonou por uma mulher no vale de Soreque, a qual se chamava Dalila.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 5, 'E vieram a ela os príncipes dos filisteus, e disseram-lhe: Engana-o e sabe em que consiste sua grande força, e como o poderíamos vencer, para que o amarremos e o atormentemos; e cada um de nós te dará mil e cem siclos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 6, 'E Dalila disse a Sansão: Eu te rogo que me declares em que consiste tua grande força, e como poderás ser acorrentado para ser atormentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 7, 'E respondeu-lhe Sansão: Se me atarem com sete vimes verdes que ainda não estejam secos, então me debilitarei, e serei como qualquer um dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 8, 'E os príncipes dos filisteus lhe trouxeram sete vimes verdes que ainda não se haviam secado, e atou-lhe com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 9, 'E estavam espias em casa dela em uma câmara. Então ela lhe disse: Sansão, os filisteus sobre ti! E ele rompeu os vimes, como se rompe uma corda de estopa quando sente o fogo: e não se soube sua força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 10, 'Então Dalila disse a Sansão: Eis que tu me enganaste, e me disseste mentiras: revela-me pois agora, eu te rogo, como poderás ser acorrentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 11, 'E ele lhe disse: Se me atarem fortemente com cordas novas, com as quais nenhuma coisa se tenha feito, eu me debilitarei, e serei como qualquer um dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 12, 'E Dalila tomou cordas novas, e atou-lhe com elas, e disse-lhe: Sansão, os filisteus sobre ti! E os espias estavam em uma câmara. Mas ele as rompeu de seus braços como um fio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 13, 'E Dalila disse a Sansão: Até agora me enganas, e tratas comigo com mentiras. Revela-me pois agora como poderás ser acorrentado. Ele então lhe disse: Se teceres sete tranças de minha cabeça com a teia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 14, 'E ela fincou a estaca, e disse-lhe: Sansão, os filisteus sobre ti! Mas despertando ele de seu sonho, arrancou a estaca do tear com a teia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 15, 'E ela lhe disse: Como dizes, Eu te amo, pois que teu coração não está comigo? Já me enganaste três vezes, e não me hás ainda descoberto em que está tua grande força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 16, 'E aconteceu que, pressionando-lhe ela cada dia com suas palavras e importunando-lhe, sua alma foi reduzida à mortal angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 17, 'Revelou-lhe, pois, todo seu coração, e disse-lhe: Nunca a minha cabeça chegou navalha; porque sou nazireu de Deus desde o ventre de minha mãe. Se for rapado, minha força se apartará de mim, e serei debilitado, e como todos os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 18, 'E vendo Dalila que ele lhe havia revelado todo seu coração, mandou chamar aos príncipes dos filisteus, dizendo: Vinde esta vez, porque ele me revelou todo seu coração. E os príncipes dos filisteus vieram a ela, trazendo em sua mão o dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 19, 'E ela fez que ele dormisse sobre seus joelhos; e chamado um homem, rapou-lhe sete tranças de sua cabeça, e começou a afligi-lo, pois sua força se apartou dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 20, 'E disse-lhe: Sansão, os filisteus sobre ti! E logo que despertou ele de seu sonho, se disse: Esta vez sairei como as outras, e me escaparei: não sabendo que o SENHOR já se havia dele apartado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 21, 'Mas os filisteus lançaram mão dele, e tiraram-lhe os olhos, e o levaram a Gaza; e o ataram com correntes, para que moesse no cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 22, 'E o cabelo de sua cabeça começou a crescer, depois que foi rapado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 23, 'Então os príncipes dos filisteus se juntaram para oferecer sacrifício a Dagom seu deus, e para alegrar-se; e disseram: Nosso deus entregou em nossas mãos a Sansão nosso inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 24, 'E vendo-o o povo, louvaram a seu deus, dizendo: Nosso deus entregou em nossas mãos a nosso inimigo, e ao destruidor de nossa terra, o qual havia matado a muitos de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 25, 'E aconteceu que, indo-se alegrando o coração deles, disseram: Chamai a Sansão, para que divirta diante de nós. E chamaram a Sansão do cárcere, e fazia de joguete diante deles; e puseram-no entre as colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 26, 'E Sansão disse ao jovem que o guiava pela mão: Aproxima-me, e faze-me segurar as colunas sobre que se sustenta a casa, para que me apoie sobre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 27, 'E a casa estava cheia de homens e mulheres: e todos os príncipes dos filisteus estavam ali; e no alto piso havia como três mil homens e mulheres, que estavam olhando o escárnio de Sansão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 28, 'Então clamou Sansão ao SENHOR, e disse: Senhor DEUS, lembra-te agora de mim, e esforça-me, te rogo, somente esta vez, ó Deus, para que de uma vez tome vingança dos filisteus, por meus dois olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 29, 'Agarrou logo Sansão as duas colunas do meio sobre as quais se sustentava a casa, e apoiou-se nelas, a uma com a direita, e a outra com a esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 30, 'E disse Sansão: Morra eu com os filisteus. E apoiando com força, caiu a casa sobre os príncipes, e sobre todo aquele povo que estava nela. E foram muitos mais os que deles matou morrendo, que os que havia matado em sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 16, 31, 'E desceram seus irmãos e toda a casa de seu pai, e tomaram-no, e levaram-no, e o sepultaram entre Zorá e Estaol, no sepulcro de seu pai Manoá. E ele julgou a Israel vinte anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 1, 'Houve um homem do monte de Efraim, que se chamava Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 2, 'O qual disse à sua mãe: Os mil e cem siclos de prata que te foram furtados, pelo que tu amaldiçoavas ouvindo-o eu, eis que eu tenho este dinheiro: eu o havia tomado. Então a mãe disse: Bendito sejas do SENHOR, filho meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 3, 'E logo que ele devolveu à sua mãe os mil e cem siclos de prata, sua mãe disse: Eu dediquei este dinheiro ao SENHOR de minha mão para ti, filho meu, para que faças uma imagem de escultura e de fundição: agora, pois, eu o devolvo a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 4, 'Mas voltando ele à sua mãe o dinheiro, tomou sua mãe duzentos siclos de prata, e deu-os ao fundidor: e ele lhe fez deles uma imagem de escultura e de fundição, a qual foi posta em casa de Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 5, 'E teve este homem Mica casa de deuses, e fez-se fazer éfode e ídolos, e consagrou um de seus filhos; e foi-lhe por sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 6, 'Nestes dias não havia rei em Israel: cada um fazia como melhor lhe parecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 7, 'E havia um jovem de Belém de Judá, da tribo de Judá, o qual era levita; e peregrinava ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 8, 'Este homem se havia partido da cidade de Belém de Judá, para ir a viver de onde achasse; e chegando ao monte de Efraim, veio à casa de Mica, para dali fazer seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 9, 'E Mica lhe disse: De onde vens? E o levita lhe respondeu: Sou de Belém de Judá, e vou a viver de onde achar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 10, 'Então Mica lhe disse: Fica-te em minha casa, e me serás em lugar de pai e sacerdote; e eu te darei dez siclos de prata por ano, e o ordinário de vestimentas, e tua comida. E o levita ficou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 11, 'Acordou, pois, o levita em morar com aquele homem, e ele o tinha como a um de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 12, 'E Mica consagrou ao levita, e aquele jovem lhe servia de sacerdote, e estava em casa de Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 17, 13, 'E Mica disse: Agora sei que o SENHOR me fará bem, pois que o levita é feito meu sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 1, 'Naqueles dias não havia rei em Israel. E em aqueles dias a tribo de Dã buscava possessão para si de onde morasse, porque até então não lhe havia caído sorte entre as tribos de Israel por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 2, 'E os filhos de Dã enviaram de sua tribo cinco homens de seus termos, homens valentes, de Zorá e Estaol, para que reconhecessem e explorassem bem a terra; e disseram-lhes: Ide e reconhecei a terra. Estes vieram ao monte de Efraim, até a casa de Mica, e ali passaram a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 3, 'E quando estavam próximos da casa de Mica, reconheceram a voz do jovem levita; e achegando-se ali, disseram-lhe: Quem te trouxe por aqui? e que fazes aqui? e que tens tu por aqui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 4, 'E ele lhes respondeu: Desta e desta maneira fez comigo Mica, e me há tomado para que seja seu sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 5, 'E eles lhe disseram: Pergunta, pois, agora a Deus, para que saibamos se há de prosperar nossa viajem que fazemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 6, 'E o sacerdote lhes respondeu: Ide em paz, que vosso viajem que fazeis é diante do SENHOR.')
